"""Generate the Ask Soony product screens (three desktop style variants plus phone, routine and after-approve)."""

from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "screens"

# ---------------------------------------------------------------- themes
THEMES = {
    "a": dict(
        name="Precise instrument",
        fonts="family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500;600",
        vars="""
  --font: "Geist", ui-sans-serif, system-ui, sans-serif; --mono: "Geist Mono", ui-monospace, Menlo, monospace;
  --num-font: "Geist Mono", ui-monospace, monospace; --num-weight: 500; --num-track: -.04em; --num-stretch: 100%;
  --page: #f3f4f6; --app: #ffffff; --sunken: #f8f9fa; --hover: #f1f3f5; --line: #e3e6ea; --line-2: #cfd4da;
  --ink: #0c1016; --ink-2: #444c58; --ink-3: #69727f; --ink-4: #a2a9b3;
  --accent: #2f5af5; --accent-ink: #ffffff; --accent-tint: #eef2ff;
  --stop: #d3281c; --stop-tint: #fdf0ef;
  --routine: #0a7c71; --routine-tint: #ebf6f4; --routine-line: #b6dfd9;
  --mark: #ffe066; --mark-soft: #fff6c7; --mark-line: #d9a900;
  --bar-done: #2b313a; --bar-plan: #d5d9df;
  --shadow-sm: 0 1px 1px rgba(12,16,22,.04); --shadow: 0 1px 2px rgba(12,16,22,.05);
  --fs: 13px; --fs-sm: 12px; --fs-xs: 11px; --fs-h: 13.5px; --fs-title: 20px; --fs-say: 18px; --fs-num: 40px; --fs-count: 28px;
  --r: 4px; --r-lg: 6px; --bw: 1px; --row-py: 10px; --pad-x: 24px; --gap: 14px; --list-w: 392px; --aside-w: 264px; --top-h: 48px;
  --title-weight: 600; --say-weight: 500;""",
        extra="",
    ),
    "b": dict(
        name="Calm operations",
        fonts="family=Instrument+Sans:wdth,wght@75..100,400..700&family=IBM+Plex+Mono:wght@400;500;600",
        vars="""
  --font: "Instrument Sans", ui-sans-serif, system-ui, sans-serif; --mono: "IBM Plex Mono", ui-monospace, Menlo, monospace;
  --num-font: "Instrument Sans", ui-sans-serif, sans-serif; --num-weight: 600; --num-track: -.035em; --num-stretch: 100%;
  --page: #f1f0ed; --app: #fdfdfc; --sunken: #f7f6f3; --hover: #f0efeb; --line: #e8e6e1; --line-2: #d6d3cc;
  --ink: #191917; --ink-2: #4c4b47; --ink-3: #75736d; --ink-4: #a9a69f;
  --accent: #2346c8; --accent-ink: #ffffff; --accent-tint: #edf0fb;
  --stop: #c62f1f; --stop-tint: #fbefed;
  --routine: #127a5f; --routine-tint: #eaf4ef; --routine-line: #bcdccd;
  --mark: #ffdf5e; --mark-soft: #fff4c2; --mark-line: #d4a300;
  --bar-done: #3a3936; --bar-plan: #dcd9d2;
  --shadow-sm: 0 1px 2px rgba(25,25,23,.05); --shadow: 0 1px 2px rgba(25,25,23,.04), 0 6px 20px -8px rgba(25,25,23,.10);
  --fs: 15px; --fs-sm: 13.5px; --fs-xs: 12px; --fs-h: 15px; --fs-title: 26px; --fs-say: 22px; --fs-num: 56px; --fs-count: 34px;
  --r: 8px; --r-lg: 14px; --bw: 1px; --row-py: 14px; --pad-x: 32px; --gap: 20px; --list-w: 420px; --aside-w: 288px; --top-h: 56px;
  --title-weight: 600; --say-weight: 500;""",
        extra="",
    ),
    "c": dict(
        name="High-contrast signal",
        fonts="family=Archivo:wdth,wght@62..125,400..900&family=JetBrains+Mono:wght@400;500;600;700",
        vars="""
  --font: "Archivo", "Helvetica Neue", Arial, sans-serif; --mono: "JetBrains Mono", ui-monospace, Menlo, monospace;
  --num-font: "Archivo", "Arial Narrow", sans-serif; --num-weight: 800; --num-track: -.01em; --num-stretch: 68%;
  --page: #ebebeb; --app: #ffffff; --sunken: #f6f6f6; --hover: #f0f0f0; --line: #e2e2e2; --line-2: #0a0a0a;
  --ink: #0a0a0a; --ink-2: #3a3a3a; --ink-3: #616161; --ink-4: #9a9a9a;
  --accent: #0a3cff; --accent-ink: #ffffff; --accent-tint: #eef1ff;
  --stop: #e10600; --stop-tint: #fff0ef;
  --routine: #00806b; --routine-tint: #e8f5f2; --routine-line: #00806b;
  --mark: #ffe500; --mark-soft: #fff7b0; --mark-line: #0a0a0a;
  --bar-done: #0a0a0a; --bar-plan: #d4d4d4;
  --shadow-sm: none; --shadow: none;
  --fs: 14px; --fs-sm: 13px; --fs-xs: 11.5px; --fs-h: 14.5px; --fs-title: 26px; --fs-say: 21px; --fs-num: 72px; --fs-count: 44px;
  --r: 0px; --r-lg: 2px; --bw: 1px; --row-py: 12px; --pad-x: 28px; --gap: 16px; --list-w: 404px; --aside-w: 272px; --top-h: 52px;
  --title-weight: 700; --say-weight: 600;""",
        extra="""
.topbar { border-bottom: 2px solid var(--ink) }
.status-band { border-bottom: 2px solid var(--ink) }
.group-h { background: var(--ink); color: #fff; letter-spacing: .06em; text-transform: uppercase; font-weight: 700 }
.group-h .c { color: #fff }
.group-h.auto { background: var(--routine); color: #fff }
.group-h.auto .c, .group-h.auto .learned { color: #fff }
.say { text-transform: none }
.dtitle { letter-spacing: -.015em }
.card, .rec, .docview, .compare .side { border-color: var(--ink) }
.btn { border-color: var(--ink) }
.count b { font-stretch: 68% }
.side .num { font-stretch: 68% }
.hl { box-shadow: inset 0 0 0 1px var(--ink) }
.rstrip { border-bottom: 2px solid var(--ink) }
""",
    ),
}

