def decision_main():
    return f"""<div class="main">
  <div class="dbar"><span>Hwaseong Memory</span><span>/</span><span>Game card 128 GB</span><span class="right">{ic('clock','s14')}Decide by Sun 10:00 · <b>in 3 h 40 min</b></span></div>
