def icon_defs(names=None):
    names = names or [k for k, v in ICONS.items() if v]
    body = "".join(f'<symbol id="i-{n}" viewBox="0 0 24 24">{ICONS[n]}</symbol>' for n in names)
    mark = (
        '<symbol id="mark" viewBox="0 0 24 24"><path d="M2.5 8V2.5H8M16 2.5h5.5V8M21.5 16v5.5H16M8 21.5H2.5V16" '
        'fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"/>'
        '<rect x="6.5" y="9.5" width="11" height="5" rx="1" fill="var(--mark)" stroke="var(--mark-line)" stroke-width=".8"/></symbol>'
    )
    return f'<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>{mark}{body}</defs></svg>'


def ic(name, cls=""):
    return f'<svg class="i {cls}" aria-hidden="true"><use href="#i-{name}"/></svg>'


def g(n):
    """Source marker: every figure points to a numbered source."""
    return f'<sup class="g" title="Source {n}">{n}</sup>'


