.srcs { display: grid; gap: 2px; margin-bottom: 18px }
.src { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 6px; padding: 7px 8px; border-radius: var(--r); align-items: start }
.src.on { background: var(--app); box-shadow: 0 0 0 1px var(--line) }
.src .g { margin: 1px 0 0; vertical-align: 0 }
.src b { font-size: var(--fs-xs); font-weight: 500; display: block; color: var(--ink) }
.src span { font: 400 10.5px/1.4 var(--mono); color: var(--ink-3); display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis }
.trail { list-style: none; margin: 0 0 0 4px; padding: 0; border-left: 1px solid var(--line-2) }
.trail li { position: relative; padding: 0 0 12px 14px; font-size: var(--fs-xs); color: var(--ink-2); line-height: 1.4 }
.trail li::before { content: ""; position: absolute; left: -4px; top: 4px; width: 7px; height: 7px; border-radius: 50%; background: var(--sunken); border: 1.5px solid var(--ink-4) }
.trail li.gate::before { background: var(--ink); border-color: var(--ink) }
.trail time { display: block; font: 500 10.5px var(--mono); color: var(--ink-3) }

/* after approve */
.done-banner { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-radius: var(--r-lg); border: 1px solid var(--line); background: var(--app); box-shadow: var(--shadow); font-size: var(--fs-sm) }
.done-banner .i { color: var(--ink) }
.done-banner b { font-weight: 600 }
.done-banner .sp { margin-left: auto; display: flex; gap: 8px; align-items: center; color: var(--ink-3); font-size: var(--fs-xs) }
.summary { display: grid; grid-template-columns: auto auto auto 1fr; gap: 16px; align-items: baseline; padding: 12px 16px; border: 1px solid var(--line); border-radius: var(--r-lg); background: var(--sunken); font-size: var(--fs-sm); color: var(--ink-2) }
.summary .num { font-size: 22px; color: var(--ink) }
.summary .num.red { color: var(--stop) }
.offer { border: 1px solid var(--routine-line); border-radius: var(--r-lg); background: var(--app); box-shadow: var(--shadow); overflow: hidden }
.offer .oh { padding: 14px 18px; background: var(--routine-tint); display: grid; gap: 3px; border-bottom: 1px solid var(--routine-line) }
.offer .oh .k { display: flex; align-items: center; gap: 7px; color: var(--routine); font-size: var(--fs-xs); font-weight: 600 }
.offer .oh h4 { font-size: calc(var(--fs-h) + 3px); letter-spacing: -.01em }
.offer .oh p { font-size: var(--fs-sm); color: var(--ink-2) }
.hflow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; padding: 18px }
.hstep { position: relative; padding: 0 16px 0 0; display: grid; gap: 6px; align-content: start }
.hstep:not(:last-child)::after { content: ""; position: absolute; top: 15px; left: 40px; right: 8px; height: 1px; background: var(--line-2) }
.hstep .ic { width: 32px; height: 32px; border-radius: var(--r); border: 1px solid var(--line-2); display: grid; place-items: center; color: var(--ink-2); background: var(--app) }
.hstep.then .ic { color: var(--routine); border-color: var(--routine-line); background: var(--routine-tint) }
.hstep.guard .ic { background: var(--ink); border-color: var(--ink); color: var(--app) }
.hstep .k { font: 600 10.5px var(--mono); color: var(--ink-3); letter-spacing: .04em; margin-top: 4px }
.hstep.then .k { color: var(--routine) }
.hstep p { font-size: var(--fs-sm); color: var(--ink); line-height: 1.4 }
.offer .of { display: flex; align-items: center; gap: 8px; padding: 12px 18px; border-top: 1px solid var(--line); background: var(--sunken) }
.offer .of .note { margin-left: auto; font-size: var(--fs-xs); color: var(--ink-3) }
"""


def page(title, theme, body, width, height=None, extra_css=""):
    t = THEMES[theme]
    size = f"width: {width}px;" + (f" height: {height}px; overflow: hidden;" if height else "")
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width={width}">
<title>{title}</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?{t['fonts']}&display=swap">
<style>
:root {{{t['vars']}
}}
{BASE_CSS}
{t['extra']}
body {{ {size} }}
{extra_css}
</style></head><body>
{icon_defs()}
{body}
</body></html>
"""


