.nav a { display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 10px; border-radius: var(--r); color: var(--ink-2); font-weight: 500; font-size: var(--fs-sm); text-decoration: none }
.nav a.on { background: var(--hover); color: var(--ink) }
.nav .n { font: 500 11px var(--mono); color: var(--routine); background: var(--routine-tint); border-radius: 4px; padding: 0 5px; line-height: 17px }
.tb-right { margin-left: auto; display: flex; align-items: center; gap: 10px }
.live { display: flex; gap: 7px; align-items: center; color: var(--ink-3); font-size: var(--fs-xs) }
.live i { width: 6px; height: 6px; border-radius: 50%; background: var(--routine) }
.search { display: flex; align-items: center; gap: 8px; height: 30px; padding: 0 6px 0 10px; width: 210px; border: 1px solid var(--line); border-radius: var(--r); color: var(--ink-3); font-size: var(--fs-sm); background: var(--sunken) }
.kbd { margin-left: auto; font: 500 10.5px var(--mono); border: 1px solid var(--line-2); border-radius: 4px; padding: 0 5px; line-height: 17px; color: var(--ink-3); background: var(--app) }
.iconbtn { width: 30px; height: 30px; display: grid; place-items: center; border-radius: var(--r); color: var(--ink-2) }
.avatar { width: 28px; height: 28px; border-radius: 50%; background: var(--hover); border: 1px solid var(--line-2); display: grid; place-items: center; font-size: 11px; font-weight: 600; color: var(--ink-2) }

/* status band */
.status-band { border-bottom: var(--bw) solid var(--line) }
.status { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 32px; align-items: center; padding: calc(var(--gap) + 4px) var(--pad-x) var(--gap) }
.say { font-size: var(--fs-say); line-height: 1.35; letter-spacing: -.015em; font-weight: var(--say-weight); max-width: 900px }
.say .stop { color: var(--stop) }
.say .calm { color: var(--ink-3) }
.count { display: flex; align-items: center; gap: 12px }
.count b { font-family: var(--num-font); font-weight: var(--num-weight); font-size: var(--fs-count); letter-spacing: var(--num-track); line-height: 1; white-space: nowrap }
.count b small { font-family: var(--font); font-size: .55em; font-weight: 500; color: var(--ink-3); margin: 0 3px 0 1px; letter-spacing: 0 }
.count span { font-size: var(--fs-xs); color: var(--ink-3); line-height: 1.35 }

/* timeline: Sat 06-22 = 16 h, night compressed to 2.5, Sun 06-20 = 14 h, after the trucks = 6. Total 38.5 */
.tl { display: grid; grid-template-columns: 96px minmax(0, 1fr); padding: 0 var(--pad-x) calc(var(--gap) + 2px) }
.tl-labels { display: grid; grid-template-rows: 22px 26px 26px; font-size: var(--fs-xs); font-weight: 500; color: var(--ink-2); align-items: center }
.tl-track { position: relative; display: grid; grid-template-rows: 22px 26px 26px }
.tl-scale { position: relative; font: 500 10.5px var(--mono); color: var(--ink-3) }
.tl-scale span { position: absolute; top: 3px; white-space: nowrap }
.lane { position: relative }
.seg { position: absolute; top: 8px; height: 10px; border-radius: calc(var(--r) / 2 + 1px) }
.seg.done { background: var(--bar-done) }
.seg.plan { background: var(--bar-plan) }
.seg.stop { background: var(--stop); border-radius: 0 3px 3px 0 }
.seg.hold { background: repeating-linear-gradient(135deg, var(--ink-3) 0 2px, transparent 2px 5px); border-radius: 0 3px 3px 0 }
.seg.spare { border: 1px dashed var(--ink-4); background: transparent }
.night { position: absolute; top: 22px; bottom: 0; left: 41.56%; width: 6.49%; background: repeating-linear-gradient(90deg, var(--line) 0 1px, transparent 1px 5px) }
.late { position: absolute; top: 0; bottom: 0; left: 84.42%; right: 0; background: repeating-linear-gradient(135deg, var(--hover) 0 4px, transparent 4px 8px); border-left: 2px solid var(--ink) }
.late .t { position: absolute; top: 3px; left: 8px; font: 500 10.5px var(--mono); color: var(--ink-3); white-space: nowrap }
.late .wall { position: absolute; top: 3px; right: calc(100% + 8px); font: 600 10.5px var(--mono); color: var(--ink); white-space: nowrap }
.nowline { position: absolute; top: 18px; bottom: 0; left: 48.92%; border-left: 1.5px solid var(--accent) }
.nowline span { position: absolute; top: -16px; left: -16px; font: 600 10px var(--mono); color: var(--accent); background: var(--accent-tint); padding: 0 4px; border-radius: 3px }
.lane-note { position: absolute; top: 4px; font-size: var(--fs-xs); white-space: nowrap; color: var(--ink-3) }
.lane-note.r { transform: translateX(-100%); padding-right: 8px }
.lane-note.stop { color: var(--stop); font-weight: 600 }
.late-card { position: absolute; top: 24px; left: 86.4%; display: flex; align-items: center; gap: 7px; font-size: var(--fs-xs); white-space: nowrap }
.late-card i { width: 9px; height: 9px; border-radius: 50%; background: var(--stop); box-shadow: 0 0 0 3px var(--stop-tint) }
.late-card b { color: var(--stop); font-weight: 600 }
.late-card span { color: var(--ink-2) }
.decide-mark { position: absolute; top: 2px; left: 58.44%; display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--ink-2); transform: translateX(-5px) }
.decide-mark i { width: 9px; height: 9px; border: 1.5px solid var(--ink); background: var(--app); transform: rotate(45deg) }

/* routine strip */
.rstrip { display: flex; align-items: center; gap: 14px; padding: 10px var(--pad-x); background: var(--routine-tint); border-bottom: var(--bw) solid var(--line); font-size: var(--fs-sm); color: var(--ink-2) }
.rstrip .badge { display: inline-flex; align-items: center; gap: 6px; color: var(--routine); font-weight: 600 }
.rstrip b { color: var(--ink); font-weight: 600 }
.rstrip .meter { margin-left: auto; display: flex; align-items: center; gap: 10px; white-space: nowrap }
.rstrip .bar { display: flex; gap: 3px }
.rstrip .bar i { width: 14px; height: 6px; border-radius: 2px; background: var(--routine-line) }
.rstrip .bar i.on { background: var(--routine) }
.rstrip a { color: var(--routine); font-weight: 500; text-decoration: none; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap }

/* body */
.body { display: grid; grid-template-columns: var(--list-w) minmax(0, 1fr) }
.list { border-right: var(--bw) solid var(--line); display: flex; flex-direction: column }
.list-head { height: 44px; display: flex; align-items: center; gap: 6px; padding: 0 12px; border-bottom: 1px solid var(--line) }
.seg-ctl { display: flex; gap: 2px; background: var(--hover); padding: 2px; border-radius: calc(var(--r) + 2px) }
.seg-ctl span { height: 26px; padding: 0 10px; display: flex; align-items: center; border-radius: var(--r); font-size: var(--fs-xs); font-weight: 500; color: var(--ink-3) }
.seg-ctl .on { background: var(--app); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,.08) }
.group-h { height: 32px; display: flex; align-items: center; gap: 8px; padding: 0 16px; font-size: var(--fs-xs); font-weight: 500; color: var(--ink-3); background: var(--sunken); border-bottom: 1px solid var(--line) }
.group-h .c { font: 500 11px var(--mono) }
.group-h.auto { color: var(--routine); background: var(--routine-tint) }
.group-h .learned { margin-left: auto; font-weight: 400; color: var(--ink-3); white-space: nowrap }
.row { display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; gap: 10px; padding: var(--row-py) 16px; border-bottom: 1px solid var(--line); align-items: start; position: relative }
.row.sel { background: var(--accent-tint) }
.row.sel::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--accent) }
.sev { margin-top: 2px; width: 16px; height: 16px; display: grid; place-items: center }
.dot { width: 8px; height: 8px; border-radius: 50% }
.dot.stop { background: var(--stop); box-shadow: 0 0 0 3px var(--stop-tint) }
.dot.need { background: var(--app); border: 2px solid var(--ink-2) }
.dot.silent { border: 1.5px dashed var(--ink-4); width: 10px; height: 10px }
.row h4 { font-size: var(--fs-h); font-weight: 500; line-height: 1.35; letter-spacing: -.005em }
.row .sub { font-size: var(--fs-xs); color: var(--ink-3); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis }
.row .due { font: 500 11.5px var(--mono); color: var(--ink-2); white-space: nowrap; margin-top: 2px }
.row .due.stop { color: var(--stop) }
.row.auto .sev { color: var(--routine) }
.row.auto h4, .row.mine h4 { color: var(--ink-2) }
.row.mine .sev { color: var(--ink-3) }
.learn-note { display: flex; align-items: center; gap: 8px; padding: 9px 16px; font-size: var(--fs-xs); color: var(--ink-3); border-bottom: 1px solid var(--line) }
.learn-note b { color: var(--routine); font-weight: 500 }

/* detail */
.detail { display: grid; grid-template-columns: minmax(0, 1fr) var(--aside-w) }
.main { padding: 0 var(--pad-x) calc(var(--gap) + 8px); display: flex; flex-direction: column; gap: var(--gap); min-width: 0 }
.dbar { height: 44px; display: flex; align-items: center; gap: 10px; border-bottom: 1px solid var(--line); margin: 0 calc(var(--pad-x) * -1); padding: 0 var(--pad-x); font-size: var(--fs-xs); color: var(--ink-3) }
.dbar .right { margin-left: auto; display: flex; align-items: center; gap: 6px; color: var(--ink-2) }
.dbar .right b { color: var(--stop); font-weight: 600 }
.dtitle { font-size: var(--fs-title); line-height: 1.2; letter-spacing: -.02em; font-weight: var(--title-weight); max-width: 34ch; margin-top: 4px }
.compare { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--gap); position: relative }
.neq { position: absolute; left: 50%; top: 58px; width: 30px; height: 30px; margin-left: -15px; border-radius: 50%; background: var(--app); border: 1px solid var(--line-2); display: grid; place-items: center; font-size: 17px; color: var(--ink-2); box-shadow: var(--shadow); z-index: 1 }
.side { border: 1px solid var(--line); border-radius: var(--r-lg); background: var(--app); box-shadow: var(--shadow); display: flex; flex-direction: column; min-width: 0; overflow: hidden }
.side .top { padding: 12px 16px 14px; display: grid; gap: 2px }
.side .k { display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--ink-3); font-weight: 500 }
.side .k .chip { margin-left: auto }
.side .num { font-size: var(--fs-num); line-height: 1; margin-top: 10px }
.side .when { font-size: var(--fs-h); font-weight: 600; margin-top: 6px }
.side .aux { font-size: var(--fs-xs); color: var(--ink-3) }
.side.doc .num, .side.doc .when { color: var(--stop) }
.chip { display: inline-flex; align-items: center; gap: 5px; font: 500 10.5px/1 var(--mono); border: 1px solid var(--line-2); border-radius: 4px; padding: 3px 5px; color: var(--ink-2); background: var(--app); white-space: nowrap }
.crop { margin-top: auto; border-top: 1px dashed var(--line-2); background: var(--sunken); padding: 12px 16px 14px; position: relative; font: 400 11.5px/1.75 var(--mono); color: var(--ink-2) }
.crop .lbl { display: flex; align-items: center; gap: 6px; font: 500 10.5px var(--mono); color: var(--ink-3); margin-bottom: 6px }
.crop .lbl span:last-child { margin-left: auto }
.ghost { display: block; height: 7px; border-radius: 2px; background: var(--line); margin: 6px 0 }
.saprow { display: grid; grid-template-columns: 34px minmax(0, 1fr) 62px 76px; gap: 8px; padding: 3px 6px; border-radius: 3px; white-space: nowrap }
.saprow.h { color: var(--ink-3); font-size: 10.5px; border-bottom: 1px solid var(--line) ; border-radius: 0 }
.saprow.dim { color: var(--ink-4) }
.saprow.on { background: var(--mark-soft); box-shadow: inset 0 0 0 1px var(--mark-line); color: var(--ink) }
.saprow span:nth-child(n+3) { text-align: right }
.trans { margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--line); font-family: var(--font); font-size: var(--fs-xs); color: var(--ink-2); line-height: 1.45; display: flex; gap: 6px }
.trans .i { color: var(--ink-3); margin-top: 1px }
.why { font-size: var(--fs); color: var(--ink-2); line-height: 1.55; max-width: 76ch }
.why b { color: var(--ink); font-weight: 600 }
.rec { border: 1px solid var(--line); border-radius: var(--r-lg); padding: 14px 16px; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 20px; background: var(--app); box-shadow: var(--shadow) }
.rec .k { font-size: var(--fs-xs); color: var(--ink-3); font-weight: 500 }
.rec h4 { font-size: calc(var(--fs-h) + 1.5px); font-weight: 600; letter-spacing: -.01em }
.rec p { font-size: var(--fs-sm); color: var(--ink-2) }
.rec .cost { grid-row: 1 / span 3; grid-column: 2; text-align: right; align-self: center }
.rec .cost b { display: block; font-family: var(--num-font); font-weight: var(--num-weight); font-stretch: var(--num-stretch); font-size: calc(var(--fs-count) * .72); letter-spacing: var(--num-track) }
.rec .cost span { font-size: var(--fs-xs); color: var(--ink-3) }
.rec .alt { grid-column: 1 / -1; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--line); display: flex; align-items: center; gap: 8px; font-size: var(--fs-sm); color: var(--ink-2) }
.rec .alt .free { margin-left: auto; font-size: var(--fs-xs); color: var(--ink-3) }
.actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap }
.btn { display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 14px; border-radius: var(--r); font: 500 var(--fs-sm) var(--font); border: 1px solid var(--line-2); background: var(--app); color: var(--ink); box-shadow: var(--shadow-sm); white-space: nowrap }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink) }
.btn.primary .kbd { background: transparent; border-color: rgba(255,255,255,.4); color: #fff; margin-left: 4px }
.btn.ghost { border-color: transparent; box-shadow: none; color: var(--ink-2); padding: 0 8px }
.btn.routine { background: var(--routine); border-color: var(--routine); color: #fff }
.hint { margin-left: 8px; display: flex; align-items: center; gap: 6px; font-size: var(--fs-xs); color: var(--ink-3) }
.hint .i { color: var(--routine) }
.aside { border-left: 1px solid var(--line); background: var(--sunken); padding: 0 16px 16px; min-width: 0 }
.aside h5 { height: 44px; display: flex; align-items: center; font-size: var(--fs-xs); font-weight: 500; color: var(--ink-3); border-bottom: 1px solid var(--line); margin: 0 -16px 10px; padding: 0 16px }
.srcs { display: grid; gap: 2px; margin-bottom: 18px }
.src { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: 6px; padding: 7px 8px; border-radius: var(--r); align-items: start }
.src.on { background: var(--app); box-shadow: 0 0 0 1px var(--line) }
.src .g { margin: 1px 0 0; vertical-align: 0 }
.src b { font-size: var(--fs-xs); font-weight: 500; display: block; color: var(--ink) }
.src span { font: 400 10.5px/1.4 var(--mono); color: var(--ink-3); display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis }
.trail { list-style: none; margin: 0 0 0 4px; padding: 0; border-left: 1px solid var(--line-2) }
.trail li { position: relative; padding: 0 0 12px 14px; font-size: var(--fs-xs); color: var(--ink-2); line-height: 1.4 }
.trail li::before { content: ""; position: absolute; left: -4px; top: 4px; width: 7px; height: 7px; border-radius: 50%; background: var(--sunken); border: 1.5px solid var(--ink-4) }
.trail li.gate::before { background: var(--ink); border-color: var(--ink) }
.trail time { display: block; font: 500 10.5px var(--mono); color: var(--ink-3) }

/* after approve */
.done-banner { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-radius: var(--r-lg); border: 1px solid var(--line); background: var(--app); box-shadow: var(--shadow); font-size: var(--fs-sm) }
.done-banner .i { color: var(--ink) }
.done-banner b { font-weight: 600 }
.done-banner .sp { margin-left: auto; display: flex; gap: 8px; align-items: center; color: var(--ink-3); font-size: var(--fs-xs) }
.summary { display: grid; grid-template-columns: auto auto auto 1fr; gap: 16px; align-items: baseline; padding: 12px 16px; border: 1px solid var(--line); border-radius: var(--r-lg); background: var(--sunken); font-size: var(--fs-sm); color: var(--ink-2) }
.summary .num { font-size: 22px; color: var(--ink) }
.summary .num.red { color: var(--stop) }
.offer { border: 1px solid var(--routine-line); border-radius: var(--r-lg); background: var(--app); box-shadow: var(--shadow); overflow: hidden }
.offer .oh { padding: 14px 18px; background: var(--routine-tint); display: grid; gap: 3px; border-bottom: 1px solid var(--routine-line) }
.offer .oh .k { display: flex; align-items: center; gap: 7px; color: var(--routine); font-size: var(--fs-xs); font-weight: 600 }
.offer .oh h4 { font-size: calc(var(--fs-h) + 3px); letter-spacing: -.01em }
.offer .oh p { font-size: var(--fs-sm); color: var(--ink-2) }
.hflow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0; padding: 18px }
.hstep { position: relative; padding: 0 16px 0 0; display: grid; gap: 6px; align-content: start }
.hstep:not(:last-child)::after { content: ""; position: absolute; top: 15px; left: 40px; right: 8px; height: 1px; background: var(--line-2) }
.hstep .ic { width: 32px; height: 32px; border-radius: var(--r); border: 1px solid var(--line-2); display: grid; place-items: center; color: var(--ink-2); background: var(--app) }
.hstep.then .ic { color: var(--routine); border-color: var(--routine-line); background: var(--routine-tint) }
.hstep.guard .ic { background: var(--ink); border-color: var(--ink); color: var(--app) }
.hstep .k { font: 600 10.5px var(--mono); color: var(--ink-3); letter-spacing: .04em; margin-top: 4px }
.hstep.then .k { color: var(--routine) }
.hstep p { font-size: var(--fs-sm); color: var(--ink); line-height: 1.4 }
.offer .of { display: flex; align-items: center; gap: 8px; padding: 12px 18px; border-top: 1px solid var(--line); background: var(--sunken) }
.offer .of .note { margin-left: auto; font-size: var(--fs-xs); color: var(--ink-3) }
"""


def page(title, theme, body, width, height=None, extra_css=""):
    t = THEMES[theme]
    size = f"width: {width}px;" + (f" height: {height}px; overflow: hidden;" if height else "")
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width={width}">
<title>{title}</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?{t['fonts']}&display=swap">
<style>
:root {{{t['vars']}
}}
{BASE_CSS}
{t['extra']}
body {{ {size} }}
{extra_css}
</style></head><body>
{icon_defs()}
{body}
</body></html>
"""


# ---------------------------------------------------------------- desktop components
def topbar():
    return f"""<div class="topbar">
  <div class="logo"><svg width="20" height="20" style="color:var(--ink)" aria-hidden="true"><use href="#mark"/></svg>Ask Soony</div>
  <div class="ws">Soony · Grand Heist 6 launch</div>
  <nav class="nav"><a class="on" href="#">{ic('inbox')}Launch</a><a href="#">{ic('workflow')}Routines <span class="n">3 today</span></a><a href="#">{ic('building')}Suppliers</a><a href="#">{ic('file')}Documents</a></nav>
  <div class="tb-right">
    <span class="live"><i></i>Watching the portal · checked 2 min ago</span>
    <span class="search">{ic('search', 's14')}Search or ask<span class="kbd">⌘K</span></span>
    <span class="iconbtn">{ic('bell')}</span><span class="avatar">FB</span>
  </div>
</div>"""


def status(after=False):
    if after:
        say = ('<span>Standard reaches the trucks if Boise confirms by 12:00.</span> '
               '<span class="calm">One decision left by 10:00. Collector\'s is on track with 2 h to spare.</span>')
        count = "13<small>h</small>36<small>min</small>"
        std = """<span class="seg done" style="left:0;width:41.56%"></span><span class="seg done" style="left:48.05%;width:1.04%"></span>
      <span class="seg plan" style="left:49.09%;width:27.53%"></span><span class="seg hold" style="left:76.62%;width:7.8%"></span>
      <span class="lane-note r" style="left:76.62%">From 17:00 on Boise's cards, waiting for confirmation</span>"""
        now, nowt = "49.09%", "06:24"
    else:
        say = ('<span class="stop">Standard runs out of game cards at 17:00 today.</span> '
               '<span>Two decisions by 10:00 fix that.</span> '
               '<span class="calm">Collector\'s is on track with 2 h to spare.</span>')
        count = "13<small>h</small>40<small>min</small>"
        std = f"""<span class="seg done" style="left:0;width:41.56%"></span><span class="seg done" style="left:48.05%;width:.87%"></span>
      <span class="seg plan" style="left:48.92%;width:27.7%"></span><span class="seg stop" style="left:76.62%;width:7.8%"></span>
      <span class="lane-note stop r" style="left:76.62%">Stops 17:00 · 20,000 cards short{g(4)}</span>"""
        now, nowt = "48.92%", "06:20"
    late = "" if after else f'<div class="late-card"><i></i><span><b>20,000 game cards</b>{g(2)} land Tue 24 Nov</span></div>'
    return f"""<div class="status-band">
  <div class="status"><p class="say">{say}</p>
    <div class="count"><b>{count}</b><span>until the trucks<br>leave, Sun 20:00</span></div></div>
  <div class="tl" role="img" aria-label="Launch timeline">
