"""Minimal Ask Soony screens: one decision at a time, a letter, not a dashboard."""

from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "screens"

CSS = """
:root {
  --ground: #fbfbfa; --ink: #18181a; --ink-2: #5d5d63; --ink-3: #93939a; --hair: #ececea; --soft: #f3f3f1;
  --accent: #2348d0; --late: #c8321f; --mark: #ffe066; --routine: #16795d;
  --big: 34px; --body: 18px; --small: 13.5px;
  --font: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, sans-serif;
}
* { box-sizing: border-box }
html, body { margin: 0 }
body { background: var(--ground); color: var(--ink); font: 400 var(--body)/1.6 var(--font); -webkit-font-smoothing: antialiased; font-variant-numeric: tabular-nums; position: relative; overflow: hidden }
p, h1 { margin: 0 }
a { color: inherit; text-decoration: none }
.i { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; vertical-align: -2px }
.small { font-size: var(--small); line-height: 1.5; color: var(--ink-3) }

.top { position: absolute; top: 0; left: 0; right: 0; height: 72px; display: flex; align-items: center; justify-content: center; font-size: var(--small); color: var(--ink-2) }
.top .mark { position: absolute; left: 32px; top: 26px; color: var(--ink) }
.top b { font-weight: 500; color: var(--ink) }
.foot { position: absolute; bottom: 32px; left: 0; right: 0; text-align: center; font-size: var(--small); color: var(--ink-3) }
.foot .r { color: var(--routine) }
.foot .r::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--routine); margin-right: 8px; vertical-align: 2px }
.foot a { color: var(--ink-2); border-bottom: 1px solid var(--hair); margin-left: 4px }

.col { width: 640px; margin: 0 auto; padding-top: 168px }
.eyebrow { font-size: var(--small); color: var(--ink-3); margin-bottom: 16px }
h1 { font-size: var(--big); line-height: 1.2; font-weight: 600; letter-spacing: -.025em }
.say { margin-top: 24px; color: var(--ink-2) }
.cite { color: var(--ink); font-weight: 500; border-bottom: 1.5px dotted var(--ink-3); padding-bottom: 1px; white-space: nowrap; cursor: pointer }
.cite.late { color: var(--late); border-bottom-color: color-mix(in srgb, var(--late) 55%, transparent) }
