.cite { color: var(--ink); font-weight: 500; border-bottom: 1.5px dotted var(--ink-3); padding-bottom: 1px; white-space: nowrap; cursor: pointer }
.cite.late { color: var(--late); border-bottom-color: color-mix(in srgb, var(--late) 55%, transparent) }
.cite.open { border-bottom-style: solid }
.cite .i { width: 13px; height: 13px; margin-left: 3px; color: var(--ink-3); vertical-align: 0 }

.source { margin-top: 20px; padding: 20px 24px; background: var(--soft); border-radius: 12px; font-size: var(--small); line-height: 1.9; color: var(--ink-2) }
.source .doc { font-size: var(--small); color: var(--ink) }
.source .hl { background: var(--mark); color: #111; border-radius: 3px; padding: 1px 4px; font-weight: 600 }
.source .meta { display: flex; justify-content: space-between; margin-top: 12px; color: var(--ink-3) }
.source .meta a { color: var(--accent) }

.rec { margin-top: 48px }
.rec .lbl { font-size: var(--small); color: var(--ink-3); margin-bottom: 6px }
.rec p { color: var(--ink) }
.rec .why { color: var(--ink-2) }
.act { margin-top: 32px; display: flex; align-items: center; gap: 24px }
.btn { display: inline-flex; align-items: center; height: 48px; padding: 0 28px; border-radius: 12px; background: var(--accent); color: #fff; font: 500 var(--body) var(--font); letter-spacing: -.005em; box-shadow: 0 1px 2px rgba(35,72,208,.25) }
.quiet { font-size: var(--body); color: var(--ink-2) }
.next { margin-top: 56px; font-size: var(--small); color: var(--ink-3) }
.next a { color: var(--ink-2) }

/* inbox + focus */
.inbox { position: absolute; top: 168px; left: 96px; width: 300px }
.inbox .h { font-size: var(--small); color: var(--ink-3); margin-bottom: 12px }
.item { display: grid; grid-template-columns: 8px 1fr auto; gap: 14px; align-items: baseline; padding: 12px 14px; margin: 0 -14px; border-radius: 10px; font-size: var(--small); color: var(--ink-2) }
.item i { width: 7px; height: 7px; border-radius: 50%; background: var(--ink-3); transform: translateY(-1px) }
.item.on { background: var(--soft); color: var(--ink); font-weight: 500 }
.item.on i { background: var(--accent) }
.item span:last-child { color: var(--ink-3); font-weight: 400 }
.split .col { margin: 0 0 0 520px; width: 640px }

/* done */
.done-ic { width: 40px; height: 40px; border-radius: 50%; background: var(--soft); display: grid; place-items: center; color: var(--ink); margin-bottom: 24px }
.done-ic .i { width: 20px; height: 20px }
.routine-line { margin-top: 28px; font-size: var(--small); color: var(--routine) }
.routine-line::before { content: ""; display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--routine); margin-right: 8px; vertical-align: 2px }

/* phone */
.phone { --big: 27px; --body: 17px; --small: 13px }
.phone .top { height: 96px; padding-top: 40px; font-size: var(--small) }
.phone .sb { position: absolute; top: 14px; left: 34px; right: 30px; display: flex; justify-content: space-between; font: 600 15px var(--font) }
.phone .sb i { width: 24px; height: 12px; border: 1.5px solid var(--ink); border-radius: 4px; display: block; position: relative }
.phone .sb i::after { content: ""; position: absolute; inset: 1.5px 6px 1.5px 1.5px; background: var(--ink); border-radius: 1.5px }
.phone .col { width: auto; padding: 132px 28px 0 }
.phone .rec { margin-top: 36px }
.phone .dock { position: absolute; left: 24px; right: 24px; bottom: 44px; display: grid; gap: 14px; justify-items: center }
.phone .dock .btn { width: 100%; justify-content: center; height: 54px; border-radius: 14px }
.phone .dock .quiet { font-size: var(--small) }
.phone .home { position: absolute; bottom: 9px; left: 50%; width: 134px; height: 5px; margin-left: -67px; border-radius: 3px; background: var(--ink) }
"""

ICONS = {
    "file": '<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M16 13H8"/><path d="M16 17H8"/>',
    "db": '<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5"/><path d="M3 12a9 3 0 0 0 18 0"/>',
    "check": '<path d="M20 6 9 17l-5-5"/>',
    "arrow": '<path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>',
}
MARK = ('<svg class="mark" width="20" height="20" viewBox="0 0 24 24" aria-label="Ask Soony"><path d="M2.5 8V2.5H8M16 2.5h5.5V8M21.5 16v5.5H16M8 21.5H2.5V16" '
        'fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square"/><rect x="6.5" y="9.5" width="11" height="5" rx="1" fill="#ffe066"/></svg>')


def ic(n):
    return f'<svg class="i" viewBox="0 0 24 24" aria-hidden="true">{ICONS[n]}</svg>'


def page(title, body, w, h, cls=""):
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width={w}">
<title>{title}</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600&display=swap">
<style>{CSS}
body {{ width: {w}px; height: {h}px }}</style></head>
<body class="{cls}">
{body}
</body></html>
"""


TOP = f'<div class="top">{MARK}<span><b>Launch in 13 h 40 min</b> · 3 decisions need you</span></div>'
FOOT = '<div class="foot"><span class="r">3 handled by your routines overnight</span> ·<a href="#">see</a></div>'


def decision(open_source=False, phone=False):
    late_cls = "cite late open" if open_source else "cite late"
    source = """<div class="source">
  <div class="doc">출하 통지서 · Shipping advice · Shipped 28,000 · Balance <span class="hl">20,000</span></div>
  <div class="doc">잔량 20,000개 · 함부르크 도착 <span class="hl">2026-11-24</span></div>
  <div>Translated from Korean: the balance of 20,000 reaches Hamburg on 24 Nov.</div>
  <div class="meta"><span>Hwaseong Memory · shipping advice, page 1</span><a href="#">Open document</a></div>
</div>""" if open_source else ""
    actions = "" if phone else """<div class="act"><a class="btn" href="#">Approve</a><a class="quiet" href="#">Other options</a></div>
<p class="next"><a href="#">Next decision</a> · 19,300 art books, not 91,300</p>"""
    return f"""<div class="col">
  <p class="eyebrow">Hwaseong Memory · decide by 10:00</p>
  <h1>20,000 game cards will arrive after launch.</h1>
  <p class="say">SAP still expects <span class="cite">48,000 by Saturday{ic('db')}</span>, but Hwaseong's shipping advice says <span class="{late_cls}">20,000 arrive Tue 24 Nov{ic('file')}</span>, after the trucks leave.</p>
  {source}
  <div class="rec"><p class="lbl">We recommend</p>
    <p>Ask Boise Semi to fly 20,000 cards for Sunday.</p>
    <p class="why">About USD 196k in air freight. Standard keeps packing past 17:00.</p></div>
  {actions}
</div>"""


def build():
    OUT.mkdir(exist_ok=True)
    W, H = 1440, 900
    (OUT / "10-focus-desktop.html").write_text(page("Ask Soony · Focus", TOP + decision() + FOOT, W, H))
    (OUT / "11-focus-source-open.html").write_text(page("Ask Soony · Focus, source open", TOP + decision(open_source=True) + FOOT, W, H))

    items = [("20,000 game cards arrive late", "10:00", True), ("19,300 art books, not 91,300", "10:00", False),
             ("No news from Yantian for 18 h", "12:00", False)]
    inbox = '<div class="inbox"><p class="h">Needs you</p>' + "".join(
        f'<div class="item{" on" if on else ""}"><i></i><span>{t}</span><span>{d}</span></div>' for t, d, on in items) + "</div>"
    (OUT / "12-inbox-focus-desktop.html").write_text(page("Ask Soony · Inbox and focus", TOP + inbox + decision() + FOOT, W, H, "split"))

    phone = f"""<div class="sb"><span>06:20</span><i></i></div>
<div class="top"><span><b>Launch in 13 h 40 min</b> · 3 need you</span></div>
{decision(phone=True)}
<div class="dock"><a class="btn" href="#">Approve</a><a class="quiet" href="#">Other options</a></div>
<div class="home"></div>"""
    (OUT / "13-focus-phone.html").write_text(page("Ask Soony · Focus, phone", phone, 390, 844, "phone"))

    done = f"""<div class="top">{MARK}<span><b>Launch in 26 h</b> · 1 decision needs you</span></div>
<div class="col">
  <div class="done-ic">{ic('check')}</div>
  <h1>Done. PackRight will print the sleeves with the current artwork.</h1>
  <p class="say">3 more confirmations from PackRight still say <span class="cite">artwork rev B{ic('file')}</span>. Handle them the same way?</p>
  <div class="act"><a class="btn" href="#">Handle all 3</a><a class="quiet" href="#">Review each</a></div>
  <p class="routine-line">From now on a routine does this for you. Anything that costs money still comes to you.</p>
</div>"""
    (OUT / "14-after-approve-minimal.html").write_text(page("Ask Soony · Done", done, W, H))
    print("ok")


if __name__ == "__main__":
    build()
